<?php
// Tampilan IDR memakai pemisah Indonesia dan membuang nol pecahan tanpa mengubah nilai tarif.
$formatRate=function($amount,$unit){$number=rtrim(rtrim(number_format((float)$amount,4,',','.'),'0'),',');return $unit==='%'?$number.' %':'Rp '.$number;};
?>
<div class="content-wrapper"><section class="content-header"><h1>Basic Harga & Riwayat Perubahan</h1></section><section class="content"><?php $this->load->view('pipeline/billing_notice'); ?>
<div class="box box-primary"><div class="box-body"><form method="get"><label>Cabang</label><select name="branch" class="form-control" onchange="this.form.submit()"><?php foreach($branches as $item): ?><option value="<?= (int)$item['SpbbID'] ?>" <?= (int)$item['SpbbID']===$branch?'selected':'' ?>><?= html_escape($item['SpbbName']) ?></option><?php endforeach; ?></select><noscript><button>Tampilkan</button></noscript></form></div></div>
<div class="row"><div class="col-md-5"><div class="box box-success"><div class="box-header"><h3 class="box-title">Tambah Harga Berlaku</h3></div><div class="box-body"><form method="post"><?php $this->load->view('pipeline/billing_token'); ?><input type="hidden" name="SpbbID" value="<?= (int)$branch ?>">
<div class="form-group"><label>Jenis harga</label><select name="ServiceCode" class="form-control" required><option value="INITIAL">Isi 9 tarif awal sesuai daftar</option><?php foreach($services as $code=>$service): ?><option value="<?= $code ?>"><?= html_escape($service[0].' / '.$service[1]) ?></option><?php endforeach; ?></select></div>
<div class="form-group"><label>Harga baru (IDR / Rupiah) atau persen</label><input type="number" min="0" step="0.0001" name="Amount" class="form-control" placeholder="Contoh: 125000 untuk Rp 125.000"><small>Mata uang default: IDR (Rupiah). Masukkan angka tanpa pemisah ribuan. Khusus PPN, masukkan nilai persen.</small></div>
<div class="form-group"><label>Satuan tarif Jasa Administrasi BBM (khusus jenis ini)</label><select name="FuelUnit" class="form-control"><option value="LITER">Per Liter — contoh Rp 125 / liter</option><option value="TON">Per TON — contoh Rp 125.000 / TON</option></select></div><div class="form-group"><label>Berlaku mulai</label><input type="date" name="EffectiveDate" required class="form-control" value="<?= set_value('EffectiveDate',date('Y-m-d')) ?>"><small>Pilih tanggal awal yang mencakup DO yang akan ditagihkan. Tarif BBM dan PPN mengikuti tanggal DO; jasa lain mengikuti akhir periode.</small></div>
