<hr><h4>Daftar tarif awal</h4><p class="text-muted">Mata uang: IDR / Rupiah (Rp). PPN ditampilkan dalam persen.</p><div class="table-responsive"><table class="table table-bordered table-striped"><thead><tr><th>Jasa</th><th>Satuan</th><th class="text-right">Harga (IDR) / Persen</th></tr></thead><tbody><?php foreach($services as $service): ?><tr><td><?= html_escape($service[0]) ?></td><td><?= html_escape($service[1]) ?></td><td class="text-right"><?= $formatRate($service[2],$service[1]) ?></td></tr><?php endforeach; ?></tbody></table></div></div></div></div>
<div class="col-md-7"><div class="box box-primary"><div class="box-header"><h3 class="box-title">Harga Berlaku Saat Ini</h3></div><div class="box-body table-responsive"><table class="table table-bordered table-striped"><thead><tr><th>Jasa</th><th>Satuan</th><th class="text-right">Harga (IDR) / Persen</th><th>Berlaku Mulai</th></tr></thead><tbody>
<?php $active=array(); foreach($history as $row) if(substr($row['EffectiveDate'],0,10)<=date('Y-m-d') && !isset($active[$row['ServiceCode']])) $active[$row['ServiceCode']]=$row; ?>
<?php foreach($services as $code=>$service): $rate=isset($active[$code])?$active[$code]:null; ?><tr><td><?= html_escape($service[0]) ?></td><td><?= html_escape($rate?$rate['Unit']:$service[1]) ?></td><td class="text-right"><?= $rate?$formatRate($rate['Amount'],$service[1]):'Belum diinput' ?></td><td><?= $rate?html_escape(substr($rate['EffectiveDate'],0,10)):'-' ?></td></tr><?php endforeach; ?></tbody></table></div></div><div class="box"><div class="box-header"><h3 class="box-title">Riwayat (tidak ditimpa)</h3></div><div class="box-body table-responsive"><table class="table table-bordered"><thead><tr><th>Berlaku</th><th>Jasa</th><th>Harga (IDR) / Persen</th><th>Alasan</th><th>Petugas / Waktu</th></tr></thead><tbody><?php foreach($history as $row): ?><tr><td><?= html_escape($row['EffectiveDate']) ?></td><td><?= html_escape($row['ServiceName'].' / '.$row['Unit']) ?></td><td><?= $formatRate($row['Amount'],$row['Unit']) ?></td><td><?= html_escape($row['Reason']) ?></td><td><?= html_escape($row['CreatedBy'].' / '.$row['CreatedAt']) ?></td></tr><?php endforeach; ?><?php if(!$history): ?><tr><td colspan="5">Belum ada harga. Simpan tarif awal terlebih dahulu.</td></tr><?php endif; ?></tbody></table></div></div></div></div></section></div>
